{
  "title": "山之谜",
  "scene": "你站在一座山的入口，四周是茂密的森林。远处的山峰隐约可见，似乎隐藏着上古神器。入口处有三块巨石，分别雕刻着凤凰、麒麟和白虎的图案。山门上刻着一行字：‘此山藏异兽，神器藏其中。非我族类毋入，谨防陷阱。’仔细观察这些图案，你会发现凤凰图案中刻着一行隐秘的文字：‘凤凰为我族，机关隐于此。’",
  "goal": "找到上古神器",
  "clue": "线索位于山门上刻的隐秘文字和凤凰图案中",
  "choices": [
    {"id": "A", "text": "仔细研究凤凰图案", "outcome": "你发现凤凰图案中刻着一行隐秘的文字：'凤凰为我族，机关隐于此。' 推开巨石后，山门缓缓开启。你听到了轻微的响动，似乎有东西在移动。", "result": "success", "next": "next_level"},
    {"id": "B", "text": "忽视图案，直接撞开巨石", "outcome": "巨石坚硬无比，你撞了半天也没有反应，山门纹丝不动。", "result": "fail", "next": "retry"},
    {"id": "C", "text": "观察麒麟和白虎图案", "outcome": "你发现麒麟和白虎图案中似乎有细微差异，但没有明显的线索，你决定继续探索。", "result": "partial", "next": "retry"}
  ]
}
